/**
 * Reference dataset for the in-browser development backend.
 *
 * This file is the canonical seed for the tables described in db/schema.sql.
 * Everything here is deterministic and hand-authored:
 *  - purpose -> field applicability is reviewed by hand (see
 *    SBI_AOF_APPLICABILITY below). It is never inferred or generated by a model.
 *  - geometry is measured against one specific artwork revision and pinned by
 *    `artworkHash`; published versions are immutable.
 */

export interface MockCatalog {
  banks: Bank[];
  formTypes: FormType[];
  bankForms: BankForm[];
  formVersions: FormVersion[];
  formPages: (FormPageSpec & { formVersionId: string })[];
  formFields: FormFieldDefinition[];
  purposes: Purpose[];
  applicability: PurposeApplicability[];
  fieldGuidance: FieldGuidance[];
}

