/**
 * purpose code -> applicable field keys, for the SBI Account Opening Form.
 * Hand-reviewed. Every other field of the version is not applicable for that
 * purpose and must be left blank on the physical form.
 */
export const SBI_AOF_APPLICABILITY: Record<string, string[]> = {
  'open-new': ['account-type', 'photo', 'full-name', 'date-of-birth', 'mobile', 'address'],
  'minor-to-major': ['full-name', 'date-of-birth', 'mobile', 'address', 'minor-guardian'],
  'update-details': ['full-name', 'mobile', 'address'],
  'change-type': ['account-type', 'full-name', 'mobile'],
  other: ['full-name', 'mobile'],
};

export function sbiFieldId(fieldKey: string): string {
  return `${SBI_AOF_VERSION_ID}::${fieldKey}`;
}

