/* ------------------------------------------------------------------- seed -- */

function buildBankForms(): BankForm[] {
  const rows: BankForm[] = [];
  for (const [bankId, formTypeIds] of Object.entries(BANK_FORM_MATRIX)) {
    for (const formTypeId of formTypeIds) {
      rows.push({ id: `${bankId}::${formTypeId}`, bankId, formTypeId, isActive: true });
    }
  }
  return rows;
}

function buildFormVersions(bankForms: BankForm[]): FormVersion[] {
  return bankForms.map((bankForm) => {
    const isSbiAof = bankForm.id === SBI_ACCOUNT_OPENING_BANK_FORM_ID;
    return {
      id: isSbiAof ? SBI_AOF_VERSION_ID : `${bankForm.id}::v1`,
      bankFormId: bankForm.id,
      // Only the measured SBI revision has a printable label so far; the other
      // rows exist so the catalogue, search and filters are complete, and are
      // surfaced to the user as "not available yet".
      versionLabel: isSbiAof ? SBI_AOF_VERSION_LABEL : 'REV-PENDING',
      artworkHash: isSbiAof ? SBI_AOF_ARTWORK_HASH : 'sha256:pending',
      status: 'published' as const,
      publishedAt: isSbiAof ? '2023-12-01T00:00:00.000Z' : '2024-01-01T00:00:00.000Z',
    };
  });
}

function buildFormFields(): FormFieldDefinition[] {
  return SBI_AOF_FIELDS.map((field, index) => ({
    id: sbiFieldId(field.fieldKey),
    formVersionId: SBI_AOF_VERSION_ID,
    page: 1,
    x: field.x,
    y: field.y,
    width: field.width,
    height: field.height,
    fieldKey: field.fieldKey,
    labelKey: field.labelKey,
    required: field.required,
    sort: index,
  }));
}

function buildPurposes(bankForms: BankForm[]): Purpose[] {
  const rows: Purpose[] = [];
  for (const bankForm of bankForms) {
    const purposeCodes = FORM_PURPOSE_MATRIX[bankForm.formTypeId] ?? [];
    purposeCodes.forEach((code, index) => {
      const catalogue = PURPOSE_CATALOGUE[code];
      if (!catalogue) return;
      rows.push({
        id: `${bankForm.id}::${code}`,
        bankFormId: bankForm.id,
        labelKey: catalogue.labelKey,
        shortLabelKey: catalogue.shortLabelKey,
        icon: catalogue.icon,
        sort: index,
      });
    });
  }
  return rows;
}

function buildApplicability(): PurposeApplicability[] {
  const rows: PurposeApplicability[] = [];
  const applicableFieldKeys = new Set(Object.values(SBI_AOF_APPLICABILITY).flat());
  for (const [purposeCode, applicableKeys] of Object.entries(SBI_AOF_APPLICABILITY)) {
    const purposeId = `${SBI_ACCOUNT_OPENING_BANK_FORM_ID}::${purposeCode}`;
    for (const fieldKey of applicableFieldKeys) {
      rows.push({
        formVersionId: SBI_AOF_VERSION_ID,
        purposeId,
        fieldId: sbiFieldId(fieldKey),
        applicable: applicableKeys.includes(fieldKey),
      });
    }
  }
  return rows;
}

function buildGuidance(): FieldGuidance[] {
  const rows: FieldGuidance[] = [];
  for (const [languageCode, seed] of Object.entries(GUIDANCE_BY_LANGUAGE) as [LanguageCode, GuidanceSeed][]) {
    for (const field of SBI_AOF_FIELDS) {
      const text = seed[field.fieldKey];
      if (!text) continue;
      rows.push({
        fieldId: sbiFieldId(field.fieldKey),
        languageCode,
        title: text.title,
        body: text.body,
        docLabel: text.docLabel,
      });
    }
  }
  return rows;
}

export function buildMockCatalog(): MockCatalog {
  const bankForms = buildBankForms();
  const formVersions = buildFormVersions(bankForms);
  return {
    banks: BANKS,
    formTypes: FORM_TYPES,
    bankForms,
    formVersions,
    formPages: SBI_AOF_PAGES.map((page) => ({ ...page, formVersionId: SBI_AOF_VERSION_ID })),
    formFields: buildFormFields(),
    purposes: buildPurposes(bankForms),
    applicability: buildApplicability(),
    fieldGuidance: buildGuidance(),
  };
}
